export function parseRange(spec: string): number[] {
  const range: number[] = [];
  const items = spec.split(/,\s*/);
  items.forEach(item => {
    if (/^\d+$/.test(item)) {
      range.push(parseInt(item, 10));
    } else if (/^\d+-\d+$/.test(item)) {
      const [start, end] = item.split('-').map(Number);
      if (start <= end) {
        for (let i = start; i <= end; i++) {
          range.push(i);
        }
      } else {
        throw new Error('Malformed range');
      }
    } else {
      throw new Error('Malformed item');
    }
  });
  return Array.from(new Set(range)).sort((a, b) => a - b);
}
